package com.p2p.escrow.web;
import com.p2p.escrow.domain.*; import com.p2p.escrow.repo.Repositories.Users; import com.p2p.escrow.security.JwtService; import jakarta.validation.constraints.*; import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/auth") public class AuthController {private final Users users;private final JwtService jwt;private final BCryptPasswordEncoder encoder=new BCryptPasswordEncoder();public AuthController(Users u,JwtService j){users=u;jwt=j;}@PostMapping("/register") public Map<String,String> register(@RequestBody Credentials c){if(users.findByEmail(c.email).isPresent())throw new IllegalStateException("Email already registered");AppUser u=new AppUser();u.email=c.email.toLowerCase();u.passwordHash=encoder.encode(c.password);users.save(u);return Map.of("token",jwt.issue(u.id));}@PostMapping("/login") public Map<String,String> login(@RequestBody Credentials c){AppUser u=users.findByEmail(c.email.toLowerCase()).filter(x->encoder.matches(c.password,x.passwordHash)).orElseThrow(()->new IllegalStateException("Invalid credentials"));return Map.of("token",jwt.issue(u.id));}public record Credentials(@Email String email,@Size(min=12,max=100) String password){} }
